// One recorded checkpoint from logTiming below -- kept instead of printed
// immediately, so every checkpoint from a run can be shown together in
// one summary at the very end (printTimings), after all the physics
// output, rather than interleaved before it.
struct TimingRecord {
  std::string label;
  std::string timestamp;
  double phase_seconds = 0.0;
  double total_seconds = 0.0;
};

// Records a wall-clock timestamp plus the elapsed time since `since` (the
// previous checkpoint) and since `start` (program start) into `records`,
// then updates `since` to now -- so a sequence of calls builds up a
// running per-phase breakdown (e.g. "how long did just the two-electron
// integrals take") without needing to store each duration separately at
// the call site.
void logTiming(const std::string& label, std::chrono::steady_clock::time_point start,
                std::chrono::steady_clock::time_point& since,
                std::vector<TimingRecord>& records) {
  const auto now_steady = std::chrono::steady_clock::now();
  const auto now_wall = std::chrono::system_clock::now();
  const std::time_t now_time_t = std::chrono::system_clock::to_time_t(now_wall);
  std::ostringstream timestamp;
  timestamp << std::put_time(std::localtime(&now_time_t), "%Y-%m-%d %H:%M:%S");
  TimingRecord record;
  record.label = label;
  record.timestamp = timestamp.str();
  record.phase_seconds = std::chrono::duration<double>(now_steady - since).count();
  record.total_seconds = std::chrono::duration<double>(now_steady - start).count();
  records.push_back(record);
  since = now_steady;
}

// Prints every checkpoint recorded by logTiming, in order, as one summary
// block. Called at the very end of a run (success or failure) instead of
// each logTiming call printing as it happens.
void printTimings(const std::vector<TimingRecord>& records) {
  if (records.empty()) return;
  std::cout << "\nTimings:\n";
  for (const auto& record : records) {
    std::cout << "  " << record.label << ": " << record.timestamp << "  (+" << std::fixed
               << std::setprecision(3) << record.phase_seconds << " s this phase, "
               << record.total_seconds << " s total)\n";
  }
  std::cout << std::setprecision(6);
}

// Prints one "  <label>: <value> Hartree" energy summary line with the
// decimal point aligned against sibling lines printed the same way,
// regardless of label length or the value's sign/integer-digit count.
// This works because the stream stays in std::fixed mode throughout
// main() (set once, near the top) -- so the number of digits after the
// decimal point is constant -- and because a common (left-justified
// label, right-justified value) field width then makes each value's
// right edge (and therefore its decimal point) land in the same column.
void printEnergyLine(const std::string& label, double value) {
  std::cout << "  " << std::setw(35) << std::left << (label + ":") << std::right
             << std::setw(20) << value << " Hartree\n";
}

// Frobenius norm and max |element| of an orbital-gradient matrix `g`
// (Hessian_opt/OrbitalGradient.h or the NON_REL/C4_DHF "efficient" fast
// paths), which only stores its p >= q half: g_qp = -conj(g_pq), so the
// full norm-squared is sum_p |g_pp|^2 + 2*sum_{p>q} |g_pq|^2 (the p<q
// "half" has the same magnitudes as its p>q mirror).
template <typename T>
void gradientNormAndMax(const rerdmft::Matrix<T>& g, double& norm, double& max_abs) {
  const std::size_t n = g.rows();
  double sum_sq = 0.0;
  max_abs = 0.0;
  for (std::size_t p = 0; p < n; ++p) {
    for (std::size_t q = 0; q <= p; ++q) {
      const double abs_val = std::abs(g(p, q));
      max_abs = std::max(max_abs, abs_val);
      sum_sq += (p == q ? 1.0 : 2.0) * abs_val * abs_val;
    }
  }
  norm = std::sqrt(sum_sq);
}

// Builds the HF/DHF-as-an-RDMFT-functional test coupling matrix
// two_rdm_h(p,q) = two_rdm_x(p,q) = occupations[p]*occupations[q] --
// see Hessian_opt/HartreeExchangeGradient.h: ordinary HF/DHF is the
// special case where Hartree and exchange share this SAME occupation-
// number-product coupling, with idempotent occupations.
rerdmft::Matrix<double> occupationOuterProduct(const std::vector<double>& occupations) {
  const std::size_t n = occupations.size();
  rerdmft::Matrix<double> m(n, n, 0.0);
  for (std::size_t p = 0; p < n; ++p) {
    for (std::size_t q = 0; q < n; ++q) {
      m(p, q) = occupations[p] * occupations[q];
    }
  }
  return m;
}

// conj(double) is a no-op; conj(complex<double>) is std::conj -- avoids
// std::conj(double)'s real-to-complex promotion gotcha (see
// Hessian_opt/OrbitalGradient.cpp's identical helper).
double scalarConj(double x) { return x; }
std::complex<double> scalarConj(std::complex<double> x) { return std::conj(x); }

// Builds the single-determinant Fock matrix directly in an orthonormal
// MO/natural-spinor basis:
//   F(p,r) = h(p,r) + sum_qs P(s,q) * (eri(p,q,r,s) - eri(p,q,s,r))
// -- the general spin-orbital-style Hartree-exchange contraction (no
// "closed-shell 1/2" factor, no AO-basis "flavor" split needed), valid
// for ANY P (in particular a density rotated away from the reference
// determinant's own diagonal one), since `eri` already fully and
// correctly represents the Coulomb operator in this basis. DEBUG-only
// finite-difference gradient/Hessian test helper -- see main() below.
template <typename T>
rerdmft::Matrix<T> singleDeterminantMoFock(const rerdmft::Matrix<T>& h,
                                            const rerdmft::Tensor4<T>& eri,
                                            const rerdmft::Matrix<T>& p) {
  const std::size_t n = h.rows();
  rerdmft::Matrix<T> f(n, n, T{});
  for (std::size_t pi = 0; pi < n; ++pi) {
    for (std::size_t ri = 0; ri < n; ++ri) {
      T sum{};
      for (std::size_t qi = 0; qi < n; ++qi) {
        for (std::size_t si = 0; si < n; ++si) {
          sum += p(si, qi) * (eri(pi, qi, ri, si) - eri(pi, qi, si, ri));
        }
      }
      f(pi, ri) = h(pi, ri) + sum;
    }
  }
  return f;
}

// E = (1/2) Re(Tr[P (h+F)]) + nuclear_repulsion -- the same formula
// C4_DHF.cpp/NonRelHartreeFock.cpp's own SCF loops use each iteration,
// evaluated here for an arbitrary (possibly non-self-consistent, e.g.
// rotated-away-from-convergence) P.
template <typename T>
double singleDeterminantMoEnergy(const rerdmft::Matrix<T>& h, const rerdmft::Tensor4<T>& eri,
                                  const rerdmft::Matrix<T>& p, double nuclear_repulsion) {
  const rerdmft::Matrix<T> f = singleDeterminantMoFock(h, eri, p);
  const std::size_t n = h.rows();
  T trace{};
  for (std::size_t i = 0; i < n; ++i) {
    for (std::size_t j = 0; j < n; ++j) {
      trace += p(i, j) * (h(j, i) + f(j, i));
    }
  }
  return 0.5 * std::real(std::complex<double>(trace)) + nuclear_repulsion;
}

// D(i,j) = sum_k occupations[k] * u(i,k) * conj(u(j,k)) -- the occupied-
// projector density expressed in the SAME fixed MO/natural-spinor basis
// as `u`'s own columns. `u` is the identity for the unperturbed
// reference, or Hessian_opt/SpinorRotation.h's spinorRotationMatrix
// (exp(-kappa)) for a rotated one -- rotating "within" the fixed MO
// basis this way needs no reference to the original AO coefficients at
// all.
template <typename T>
rerdmft::Matrix<T> densityFromRotation(const rerdmft::Matrix<T>& u,
                                        const std::vector<double>& occupations) {
  const std::size_t n = u.rows();
  rerdmft::Matrix<T> d(n, n, T{});
  for (std::size_t i = 0; i < n; ++i) {
    for (std::size_t j = 0; j < n; ++j) {
      T sum{};
      for (std::size_t k = 0; k < n; ++k) {
        if (occupations[k] == 0.0) continue;
        sum += T(occupations[k]) * u(i, k) * scalarConj(u(j, k));
      }
      d(i, j) = sum;
    }
  }
  return d;
}

// DEBUG-only: validates Hessian_opt/OrbitalGradient.h's analytic g_pq
// (and previews the, so far unimplemented, orbital Hessian) against
// finite differences of the actual energy functional at MO-basis
// orbitals rotated by a small kappa -- built purely from `h`/`eri` and
// SpinorRotation.h's U_rot = exp(-kappa), never touching the AO basis
// or re-running an SCF. `p_idx` (e.g. LUMO) must be > `q_idx` (e.g.
// HOMO) so `analytic_g_pq` can be read directly off `gradient` (which,
// per OrbitalGradient.h, only stores p >= q). Central differences:
//   g_pq (numerical)     ~ [E(+h) - E(-h)] / (2h)
//   H_pq,pq (numerical)  ~ [E(+h) - 2 E(0) + E(-h)] / h^2
// at a few shrinking step sizes h, to show the expected O(h^2)
// convergence toward a stable value.
//
// The generator kappa_pq is complex in general (T = std::complex<double>
// for C4_DHF's genuinely complex spinors; T = double, i.e. real
// antisymmetric only, for NON_REL's real-valued HF orbitals -- the type
// system enforces this, there is no way to build an imaginary kappa in
// the T = double instantiation). A single independent real perturbation
// direction moves EITHER the real part x = Re(kappa_pq) (kappa_pq = +x,
// kappa_qp = -x, an antisymmetric real pair) OR, only when T =
// std::complex<double>, the imaginary part y = Im(kappa_pq) (kappa_pq =
// kappa_qp = iy -- anti-Hermiticity forces kappa_qp = -conj(kappa_pq) =
// -conj(iy) = iy, i.e. this direction moves BOTH entries to the SAME
// value, not opposite ones; verified numerically against
// scipy.linalg.expm before implementing). Expanding U_rot = exp(-kappa)
// = I - kappa + O(kappa^2) gives, to first order in EITHER direction,
// D_pq(kappa) = -kappa_pq exactly (using occupations(p)=0,
// occupations(q)=1; also verified numerically). Since E(D) = Tr[D h] +
// (1/2) Tr[D G(D)] with G linear and self-adjoint (Tr[D1 G(D2)] =
// Tr[D2 G(D1)], from the eri exchange symmetry <AB|CD> = <BA|DC>),
// dE/dD_pq = F_mine(q,p) where F_mine is singleDeterminantMoFock -- and
// F_mine is Hermitian for any Hermitian D (shown the same way, using
// <AB|CD>* = <CD|AB>). Chaining through both D_pq and D_qp along each
// direction gives
//   dE/dx = -(F_mine(q,p) + F_mine(p,q)) = -2*Re(F_mine(p,q))
//   dE/dy = i*(F_mine(p,q) - F_mine(q,p)) = -2*Im(F_mine(p,q))
// hartreeExchangeFockMatrix's F (F_theirs) satisfies, for idempotent
// occupations(p)=0/occupations(q)=1, F_theirs(p,q) =
// occupations(q)*F_mine(q,p) (direct substitution), which reduces the
// UNSCALED Dyall combination F_theirs(q,p) - conj(F_theirs(p,q)) =
// (occupations(p)-occupations(q))*F_mine(p,q) = -F_mine(p,q). So
// dE/dx = 2*Re(-F_mine(p,q)) and dE/dy = 2*Im(-F_mine(p,q)) exactly --
// which is precisely `gradient(p_idx, q_idx)` as returned by
// OrbitalGradient.h's `orbitalGradient` (its factor of 2 was chosen,
// see that header, EXACTLY so this equality holds with no further
// scaling needed here): the unscaled Dyall combination is the
// coefficient for ONE of the two antisymmetric-pair entries (p,q)/
// (q,p), while each finite-difference direction below moves both at
// once, picking up the other's equal contribution too -- which is
// exactly what `orbitalGradient`'s built-in factor of 2 accounts for.
// Confirmed against this exact test: DHF's numerical g_pq (real-step
// direction) converges to `gradient(p_idx, q_idx)` to ~0.1% (limited by
// floating-point cancellation in E(+h)-E(-h) at the ~1e-8 Hartree
// gradient scale, not a bug -- the residual grows, not shrinks, at
// smaller h, the signature of roundoff rather than truncation error).
// Renders to a string (rather than printing directly) so the CALLER can
// decide where in the overall report this appears -- built right after
// each SCF's own results become available, but intended to be printed
// later, alongside the final gradient-norm report (see main() below).
// This project builds the analytic HF/DHF orbital gradient THREE
// independent ways; `gradient` is the RDMFT-ansatz one
// (HartreeExchangeGradient.h's hartreeExchangeFockMatrix -> orbitalGradient,
// O(n^3)) actually compared against the numerical values below.
// `gradient_general` and `gradient_efficient` are the other two, printed
// alongside it purely as further independent cross-checks at this exact
// (p_idx,q_idx) element -- all three are mathematically equivalent for
// the idempotent HF/DHF occupations used here (already cross-checked in
// aggregate via the gradient-norm summary), so this additionally
// confirms that equivalence holds element-by-element, not just in
// Frobenius norm/max|g_pq|.
// `gradient_general`: GeneralizedFock.h's generalizedFockMatrix (dense
// 2-RDM, O(n^5)) -> orbitalGradient. Passed as a possibly-null pointer
// since this contraction is only actually computed by the caller when
// VERBOSE > 0 (see main.cpp/Input.h); nullptr skips this line entirely.
// `gradient_efficient`: the HF/DHF-specific O(n^4) shortcut
// (NON_REL/NonRelOrbitalGradient.h's nonRelOrbitalGradientEfficient or
// C4_DHF/RkbOrbitalGradient.h's dhfOrbitalGradientEfficient, built
// directly from the converged c_matrix/c_dhf, no 2-RDM at all) -- cheap
// enough to always be available whenever DEBUG is on, so this one is a
// plain reference, not a nullable pointer.
template <typename T>
std::string finiteDifferenceCheckReport(const std::string& label, const rerdmft::Matrix<T>& h,
                                         const rerdmft::Tensor4<T>& eri,
                                         const std::vector<double>& occupations,
                                         std::size_t p_idx, std::size_t q_idx,
                                         double nuclear_repulsion,
                                         const rerdmft::Matrix<T>& gradient,
                                         const rerdmft::Matrix<T>* gradient_general,
                                         const rerdmft::Matrix<T>& gradient_efficient) {
  const std::size_t n = h.rows();
  rerdmft::Matrix<T> identity(n, n, T{});
  for (std::size_t i = 0; i < n; ++i) identity(i, i) = T(1.0);
  const rerdmft::Matrix<T> d0 = densityFromRotation(identity, occupations);
  const double e0 = singleDeterminantMoEnergy(h, eri, d0, nuclear_repulsion);
  // OrbitalGradient.h's orbitalGradient already includes the factor of
  // 2 derived above -- compare directly against the numerical g_pq
  // values printed below, no further scaling needed here.
  const std::complex<double> analytic_g_pq = std::complex<double>(gradient(p_idx, q_idx));
  const std::complex<double> analytic_g_pq_efficient =
      std::complex<double>(gradient_efficient(p_idx, q_idx));

  std::ostringstream out;
  out << "\n"
      << label << " finite-difference gradient/Hessian check (p=" << p_idx
      << " [virtual], q=" << q_idx << " [occupied]):\n";
  out << "  E(kappa=0):        " << std::setprecision(12) << e0
      << "  (expect: converged total electronic+nuclear energy)\n";
  out << "  Analytic g_pq (Hessian_opt/OrbitalGradient.h, includes its "
         "deliberate factor of 2 -- see derivation above): "
      << analytic_g_pq << "\n";
  if (gradient_general != nullptr) {
    const std::complex<double> analytic_g_pq_general =
        std::complex<double>((*gradient_general)(p_idx, q_idx));
    out << "  Analytic g_pq (GeneralizedFock.h, dense 2-RDM, general path -- "
           "cross-check, |diff| from the line above: "
        << std::abs(analytic_g_pq_general - analytic_g_pq) << "): " << analytic_g_pq_general
        << "\n";
  }
  out << "  Analytic g_pq (NonRelOrbitalGradient.h/RkbOrbitalGradient.h, "
         "HF/DHF-specific efficient O(n^4) path -- cross-check, |diff| from "
         "the first line: "
      << std::abs(analytic_g_pq_efficient - analytic_g_pq) << "): " << analytic_g_pq_efficient
      << "\n";
  out << std::setprecision(6);

  for (const double step : {1e-2, 1e-3, 1e-4}) {
    rerdmft::Matrix<T> kappa_plus(n, n, T{});
    kappa_plus(p_idx, q_idx) = T(step);
    kappa_plus(q_idx, p_idx) = T(-step);
    const rerdmft::Matrix<T> d_plus =
        densityFromRotation(rerdmft::spinorRotationMatrix(kappa_plus), occupations);
    const double e_plus = singleDeterminantMoEnergy(h, eri, d_plus, nuclear_repulsion);

    rerdmft::Matrix<T> kappa_minus(n, n, T{});
    kappa_minus(p_idx, q_idx) = T(-step);
    kappa_minus(q_idx, p_idx) = T(step);
    const rerdmft::Matrix<T> d_minus =
        densityFromRotation(rerdmft::spinorRotationMatrix(kappa_minus), occupations);
    const double e_minus = singleDeterminantMoEnergy(h, eri, d_minus, nuclear_repulsion);

    const double g_numerical = (e_plus - e_minus) / (2.0 * step);
    const double h_numerical = (e_plus - 2.0 * e0 + e_minus) / (step * step);
    out << "  step = " << std::setprecision(3) << step << std::setprecision(10)
        << "   Re(kappa) step: numerical g_pq = " << g_numerical
        << "   numerical H_pq,pq = " << h_numerical << std::setprecision(6) << "\n";

    // Imaginary-direction check: only representable when T is genuinely
    // complex (C4_DHF's spinor basis) -- kappa_pq = kappa_qp = i*step
    // here (see derivation above), not an antisymmetric real pair.
    // NON_REL's real orbitals (T = double) have no imaginary direction
    // to test, so this is skipped entirely for that instantiation.
    if constexpr (std::is_same_v<T, std::complex<double>>) {
      const std::complex<double> i_step(0.0, step);
      rerdmft::Matrix<T> kappa_plus_im(n, n, T{});
      kappa_plus_im(p_idx, q_idx) = i_step;
      kappa_plus_im(q_idx, p_idx) = i_step;
      const rerdmft::Matrix<T> d_plus_im =
          densityFromRotation(rerdmft::spinorRotationMatrix(kappa_plus_im), occupations);
      const double e_plus_im = singleDeterminantMoEnergy(h, eri, d_plus_im, nuclear_repulsion);

      rerdmft::Matrix<T> kappa_minus_im(n, n, T{});
      kappa_minus_im(p_idx, q_idx) = -i_step;
      kappa_minus_im(q_idx, p_idx) = -i_step;
      const rerdmft::Matrix<T> d_minus_im =
          densityFromRotation(rerdmft::spinorRotationMatrix(kappa_minus_im), occupations);
      const double e_minus_im = singleDeterminantMoEnergy(h, eri, d_minus_im, nuclear_repulsion);

      const double g_numerical_im = (e_plus_im - e_minus_im) / (2.0 * step);
      const double h_numerical_im = (e_plus_im - 2.0 * e0 + e_minus_im) / (step * step);
      out << "           " << std::setprecision(3) << step << std::setprecision(10)
          << "   Im(kappa) step: numerical g_pq = " << g_numerical_im
          << "   numerical H_pq,pq = " << h_numerical_im << std::setprecision(6) << "\n";
    }
  }
  return out.str();
}

// E = sum h*D + sum eri*Gamma_wick(D), Gamma_wick(D)_pqrs = (1/2)(D_pr D_qs
// - D_ps D_qr) -- the UNCONDITIONALLY exact single-determinant energy for
// ANY idempotent D (no assumption on eri beyond GeneralizedFock.h's own
// Hermiticity/exchange symmetry; verified against a direct many-body
// calculation at a large finite kappa, both with and without the extra
// "particle-permutation" symmetry eri(A,B,C,D)=eri(C,D,A,B) that real
// (AO-derived) integrals happen to also have). Deliberately NOT
// `singleDeterminantMoFock`/`singleDeterminantMoEnergy` (used by
// finiteDifferenceCheckReport above for the GRADIENT check): that
// formula turned out to silently rely on the extra particle-permutation
// symmetry to reproduce the true energy at FINITE kappa (fine for
// water's real AO-derived eri, which has it, but not general) --
// avoided here entirely so this Hessian check carries no such caveat.
// O(n^4) per call, fine for a one-off finite-difference check.
template <typename T>
double wickSingleDeterminantEnergy(const rerdmft::Matrix<T>& h, const rerdmft::Tensor4<T>& eri,
                                    const rerdmft::Matrix<T>& d, double nuclear_repulsion) {
  const std::size_t n = h.rows();
  T energy{};
  for (std::size_t i = 0; i < n; ++i) {
    for (std::size_t j = 0; j < n; ++j) {
      energy += h(i, j) * d(i, j);
    }
  }
  for (std::size_t p = 0; p < n; ++p) {
    for (std::size_t q = 0; q < n; ++q) {
      for (std::size_t r = 0; r < n; ++r) {
        for (std::size_t s = 0; s < n; ++s) {
          const T gamma = T(0.5) * (d(p, r) * d(q, s) - d(p, s) * d(q, r));
          energy += eri(p, q, r, s) * gamma;
        }
      }
    }
  }
  return std::real(std::complex<double>(energy)) + nuclear_repulsion;
}

// DEBUG-only: validates Hessian_opt/HartreeExchangeHessian.h's cheap,
// Hartree/exchange-only analytic Hess_pq,rs (always shown, ALWAYS runs
// under DEBUG TRUE regardless of VERBOSE -- cheap, like
// hartreeExchangeFockMatrix's own gradient) against a genuine 2D finite
// difference
//   d^2E/dt_pq dt_rs ~ [E(+h,+h) - E(+h,-h) - E(-h,+h) + E(-h,-h)] / (4h^2)
// at a real (p_idx,q_idx) =/= (r_idx,s_idx) pair (an OFF-DIAGONAL
// element -- the diagonal case is already covered by
// finiteDifferenceCheckReport's own "numerical H_pq,pq" estimate),
// using wickSingleDeterminantEnergy above (never
// singleDeterminantMoFock, see its own comment for why) so this check
// carries no eri-symmetry caveat. `analytic_hess_general`
// (GeneralizedHessian.h's fully general, expensive path) is printed
// alongside it, with their |diff|, ONLY when the caller actually
// computed it (VERBOSE > 0, see main() below) -- mirrors exactly how
// finiteDifferenceCheckReport's `gradient_general` is a nullable
// pointer for the SAME reason.
//
// `analytic_hess_imag`/`analytic_hess_imag_general` are the analogous
// IMAGINARY-step direction (Hessian_opt/*.h's `*HessianElementImag`),
// checked against a 2D finite difference using
// kappa_pq = kappa_qp = i*step (see finiteDifferenceCheckReport's own
// imaginary-direction derivation) instead of the antisymmetric real
// pair -- only meaningful for T = std::complex<double> (C4_DHF), so
// both are nullable pointers ALWAYS passed as nullptr for T = double
// (NON_REL), exactly mirroring finiteDifferenceCheckReport's own
// `if constexpr` gating for the gradient's imaginary direction.
template <typename T>
std::string hessianFiniteDifferenceReport(const std::string& label, const rerdmft::Matrix<T>& h,
                                           const rerdmft::Tensor4<T>& eri,
                                           const std::vector<double>& occupations,
                                           std::size_t p_idx, std::size_t q_idx,
                                           std::size_t r_idx, std::size_t s_idx,
                                           double nuclear_repulsion, T analytic_hess,
                                           const T* analytic_hess_general,
                                           const T* analytic_hess_imag,
                                           const T* analytic_hess_imag_general) {
  const std::size_t n = h.rows();
  auto kappa_pair = [&](std::size_t a, std::size_t b, T step) {
    rerdmft::Matrix<T> kappa(n, n, T{});
    kappa(a, b) = step;
    kappa(b, a) = -step;
    return kappa;
  };
  auto energy_at = [&](const rerdmft::Matrix<T>& kappa1, const rerdmft::Matrix<T>& kappa2) {
    rerdmft::Matrix<T> kappa_sum(n, n, T{});
    for (std::size_t i = 0; i < n; ++i) {
      for (std::size_t j = 0; j < n; ++j) {
        kappa_sum(i, j) = kappa1(i, j) + kappa2(i, j);
      }
    }
    const rerdmft::Matrix<T> d =
        densityFromRotation(rerdmft::spinorRotationMatrix(kappa_sum), occupations);
    return wickSingleDeterminantEnergy(h, eri, d, nuclear_repulsion);
  };

  std::ostringstream out;
  out << "\n"
      << label << " finite-difference HESSIAN check (p=" << p_idx << ",q=" << q_idx
      << ",r=" << r_idx << ",s=" << s_idx << "):\n";
  out << "  Analytic Hess_pq,rs (Hessian_opt/HartreeExchangeHessian.h, cheap): "
      << std::complex<double>(analytic_hess) << "\n";
  if (analytic_hess_general != nullptr) {
    out << "  Analytic Hess_pq,rs (Hessian_opt/GeneralizedHessian.h, dense "
           "2-RDM, general path -- cross-check, |diff| from the line above: "
        << std::abs(std::complex<double>(*analytic_hess_general) -
                    std::complex<double>(analytic_hess))
        << "): " << std::complex<double>(*analytic_hess_general) << "\n";
  }
  for (const double step : {1e-2, 1e-3, 1e-4}) {
    const rerdmft::Matrix<T> kp = kappa_pair(p_idx, q_idx, T(step));
    const rerdmft::Matrix<T> km = kappa_pair(p_idx, q_idx, T(-step));
    const rerdmft::Matrix<T> kr = kappa_pair(r_idx, s_idx, T(step));
    const rerdmft::Matrix<T> ks = kappa_pair(r_idx, s_idx, T(-step));
    const double e_pp = energy_at(kp, kr);
    const double e_pm = energy_at(kp, ks);
    const double e_mp = energy_at(km, kr);
    const double e_mm = energy_at(km, ks);
    const double d2_numerical = (e_pp - e_pm - e_mp + e_mm) / (4.0 * step * step);
    out << "  step = " << std::setprecision(3) << step << std::setprecision(10)
        << "   Re(kappa) step: numerical Hess_pq,rs = " << d2_numerical << std::setprecision(6)
        << "\n";
  }

  // Imaginary-direction check: only representable when T is genuinely
  // complex (C4_DHF's spinor basis) -- kappa_pq = kappa_qp = i*step and
  // kappa_rs = kappa_sr = i*step' (see finiteDifferenceCheckReport's
  // own imaginary-direction derivation), not antisymmetric real pairs.
  // NON_REL's real orbitals (T = double) have no imaginary direction to
  // test, so both `analytic_hess_imag*` pointers are always nullptr
  // there and this whole block is skipped.
  if constexpr (std::is_same_v<T, std::complex<double>>) {
    if (analytic_hess_imag != nullptr) {
      out << "  Analytic Hess^yy_pq,rs (Hessian_opt/HartreeExchangeHessian.h, cheap, "
             "IMAGINARY direction): "
          << *analytic_hess_imag << "\n";
      if (analytic_hess_imag_general != nullptr) {
        out << "  Analytic Hess^yy_pq,rs (Hessian_opt/GeneralizedHessian.h, dense "
               "2-RDM, general path -- cross-check, |diff| from the line above: "
            << std::abs(*analytic_hess_imag_general - *analytic_hess_imag)
            << "): " << *analytic_hess_imag_general << "\n";
      }
      auto kappa_pair_imag = [&](std::size_t a, std::size_t b, double y) {
        rerdmft::Matrix<T> kappa(n, n, T{});
        const std::complex<double> val(0.0, y);
        kappa(a, b) = val;
        kappa(b, a) = val;
        return kappa;
      };
      for (const double step : {1e-2, 1e-3, 1e-4}) {
        const rerdmft::Matrix<T> kp = kappa_pair_imag(p_idx, q_idx, step);
        const rerdmft::Matrix<T> km = kappa_pair_imag(p_idx, q_idx, -step);
        const rerdmft::Matrix<T> kr = kappa_pair_imag(r_idx, s_idx, step);
        const rerdmft::Matrix<T> ks = kappa_pair_imag(r_idx, s_idx, -step);
        const double e_pp = energy_at(kp, kr);
        const double e_pm = energy_at(kp, ks);
        const double e_mp = energy_at(km, kr);
        const double e_mm = energy_at(km, ks);
        const double d2_numerical = (e_pp - e_pm - e_mp + e_mm) / (4.0 * step * step);
        out << "  step = " << std::setprecision(3) << step << std::setprecision(10)
            << "   Im(kappa) step: numerical Hess_pq,rs = " << d2_numerical
            << std::setprecision(6) << "\n";
      }
    }
  }
  return out.str();
}

// Builds the FULL orbital-rotation Hessian (Hessian_opt/
// HartreeExchangeHessian.h's cheap Hartree/exchange path, ALL
// independent real-step pairs p>q over the FULL orbital space -- for
// C4_DHF this includes the negative-energy branch, exactly as
// hartreeExchangeFockMatrix/orbitalGradient already do) and
// diagonalizes it (LinearAlgebra.h's diagonalizeSymmetric for T =
// double, diagonalizeHermitian for T = std::complex<double>) to check
// whether the converged SCF solution is a genuine MINIMUM (every
// eigenvalue >= 0) or a SADDLE POINT (some strictly negative) with
// respect to real orbital rotations -- e.g. DHF is expected to show
// negative eigenvalues from rotations mixing occupied positive-energy
// orbitals into the negative-energy branch, unlike NON_REL's genuine
// minimum. EXPENSIVE (see HartreeExchangeHessian.h). Renders to a
// string (rather than printing directly) so the CALLER can decide
// where in the overall report this appears -- built right after each
// SCF's own DEBUG cross-checks, but intended to be printed later,
// alongside the final gradient/Hessian-norm report (see main() below),
// exactly like finiteDifferenceCheckReport/hessianFiniteDifferenceReport.
// The logTiming calls below are NOT deferred -- they record elapsed
// time into `timing_records` at the point the work actually happens,
// independent of when the returned text is printed.
// `expected_n_negative`, when non-negative, is printed as a reference
// alongside the actual negative-eigenvalue count -- for C4_DHF, the
// number of occupied positive-energy spinors times the number of
// negative-energy spinors each can rotate into
// (Number_Negative_Energy_States * Number_Electrons) is a simple
// counting-argument LOWER BOUND on how many independent rotation
// directions couple an occupied positive-energy spinor to the
// negative-energy branch, each expected to carry negative curvature --
// NOT a proven exact count (degeneracies/symmetry could make the true
// count differ), just a sanity-check reference. Pass -1 (the default)
// when no such reference applies (e.g. NON_REL, which has no
// negative-energy branch at all).
template <typename T>
std::string buildFullHessianReport(const std::string& label, const rerdmft::Matrix<T>& h,
                                    const rerdmft::Tensor4<T>& eri,
                                    const std::vector<double>& occupations,
                                    const rerdmft::Matrix<double>& hx_test,
                                    const rerdmft::Matrix<T>& fock,
                                    std::chrono::steady_clock::time_point t_start,
                                    std::chrono::steady_clock::time_point& t_checkpoint,
                                    std::vector<TimingRecord>& timing_records,
                                    long long expected_n_negative = -1) {
  const std::size_t n = h.rows();
  const auto pair_indices = rerdmft::hessianPairIndices(n);
  const auto full_hessian =
      rerdmft::hartreeExchangeHessianMatrix(h, eri, occupations, hx_test, hx_test, fock,
                                             pair_indices);
  logTiming(label + " full cheap Hessian matrix built (" +
                std::to_string(pair_indices.size()) + "x" +
                std::to_string(pair_indices.size()) + ")",
            t_start, t_checkpoint, timing_records);

  std::vector<double> eigenvalues;
  if constexpr (std::is_same_v<T, double>) {
    eigenvalues = rerdmft::diagonalizeSymmetric(full_hessian).eigenvalues;
  } else {
    eigenvalues = rerdmft::diagonalizeHermitian(full_hessian).eigenvalues;
  }
  logTiming(label + " full Hessian diagonalized", t_start, t_checkpoint, timing_records);

  constexpr double kZeroTolerance = 1e-6;
  std::size_t n_negative = 0;
  std::size_t n_near_zero = 0;
  std::size_t n_positive = 0;
  for (const double eigenvalue : eigenvalues) {
    if (eigenvalue < -kZeroTolerance) {
      ++n_negative;
    } else if (eigenvalue > kZeroTolerance) {
      ++n_positive;
    } else {
      ++n_near_zero;
    }
  }

  std::ostringstream out;
  out << "\n"
      << label
      << " full orbital-rotation Hessian (Hessian_opt/HartreeExchangeHessian.h, cheap "
         "path, "
      << pair_indices.size() << "x" << pair_indices.size() << ", real-step pairs only):\n";
  out << "  Eigenvalues: " << n_negative << " negative, " << n_near_zero
      << " near-zero (|lambda| <= " << kZeroTolerance << "), " << n_positive << " positive\n";
  if (expected_n_negative >= 0) {
    out << "  Expected negative eigenvalues (Number_Negative_Energy_States * "
           "Number_Electrons, reference only): "
        << expected_n_negative << "\n";
  }
  out << "  min eigenvalue: " << std::setprecision(10) << eigenvalues.front()
      << "   max eigenvalue: " << eigenvalues.back() << std::setprecision(6) << "\n";
  out << "  "
      << (n_negative == 0
              ? "Consistent with a MINIMUM (no negative eigenvalues)."
              : "NOT a minimum -- negative eigenvalue(s) found, consistent with a "
                "SADDLE POINT.")
      << "\n";
  return out.str();
}

// Called after every HF/DHF calculation whenever Input::has_functional()
// is true (FUNCTIONAL was explicitly given -- NOT gated by DEBUG, but
// SKIPPED entirely with no FUNCTIONAL keyword at all, since there is
// then no RDMFT functional to evaluate): generates fractional initial
// occupations (Occ_opt/OccupationInit.h, via the input's
// OCCUPATION_INIT method -- PROPORTIONAL by default, or FERMI_DIRAC at
// TEMPERATURE) for the converged HF/DHF orbitals, evaluates the
// FUNCTIONAL keyword's JK-only density matrix functional
// (Occ_opt/JK_only.h) on those SAME converged orbitals with the new,
// fractional occupations, then OPTIMIZES the occupations further via
// Occ_opt/SQP.h at those same fixed orbitals -- i.e. a genuinely
// fractional-occupation RDMFT single-point energy (plus an
// occupation-number-optimized one), not the trivial idempotent-
// occupation HF/DHF energy computed elsewhere in this file. The
// returned string is printed right after the corresponding
// "Total ... energy" line (see the call sites' own std::cout placement
// in main()), never before it.
//
// `orbital_energies_active` are the orbital energies actually competing
// for the `n_electrons` available (SPIN-orbital/spinor energies, at
// most singly occupiable each); `n_inactive_below` is how many
// additional orbitals sit BELOW `orbital_energies_active` in the full
// `h`/`eri` index space and are held at EXACTLY zero occupation instead
// of being smeared -- for C4_DHF, this excludes the negative-energy
// (Dirac sea) branch from thermal population entirely (matches this
// project's existing no-pair convention, e.g. occupiedPositiveEnergyDensity)
// rather than relying on it being numerically negligible at a physical
// temperature; for NON_REL it is always 0 (every spin-orbital competes).
//
// `f_l` for JK_only's BBC2 functional (the only one that needs it) is
// SIMPLIFIED here to round(n_electrons) -- the number of "nominally
// occupied" spin-orbitals/spinors at T=0 -- since properly partitioning
// weakly/strongly occupied orbitals for a genuinely fractional-occupation
// reference is its own open question, not needed by the MULLER-only
// tests this was built for; revisit if a real BBC2 run is asked for.
template <typename T>
std::string buildFunctionalReport(const std::string& label, const rerdmft::Matrix<T>& h,
                                   const rerdmft::Tensor4<T>& eri,
                                   const std::vector<double>& orbital_energies_active,
                                   std::size_t n_inactive_below, double n_electrons,
                                   double temperature_kelvin, const std::string& functional_name,
                                   const std::string& occupation_init_name,
                                   double nuclear_repulsion_energy,
                                   std::chrono::steady_clock::time_point t_start,
                                   std::chrono::steady_clock::time_point& t_checkpoint,
                                   std::vector<TimingRecord>& timing_records) {
  const std::size_t n_total = h.rows();
  constexpr double kOccupationEpsilon = 1e-6;
  const auto occupation_init_method = rerdmft::parseOccupationInitMethod(occupation_init_name);
  const auto occupations_active = rerdmft::generateInitialOccupations(
      occupation_init_method, orbital_energies_active, n_electrons, temperature_kelvin,
      kOccupationEpsilon);
  logTiming(label + " initial occupations generated (OCCUPATION_INIT " + occupation_init_name +
                ", FUNCTIONAL " + functional_name + ")",
            t_start, t_checkpoint, timing_records);

  std::vector<double> occupations(n_total, 0.0);
  for (std::size_t i = 0; i < occupations_active.size(); ++i) {
    occupations[n_inactive_below + i] = occupations_active[i];
  }

  const auto functional = rerdmft::parseJkFunctional(functional_name);
  const auto two_rdm_h = rerdmft::jkHartreeCoupling(occupations);
  const auto f_l = static_cast<std::size_t>(std::lround(n_electrons));
  const auto two_rdm_x = rerdmft::jkExchangeCoupling(functional, occupations, f_l);
  logTiming(label + " JK-only two_rdm_H/two_rdm_X built (" + functional_name + ")", t_start,
            t_checkpoint, timing_records);

  const double electronic_energy =
      rerdmft::hartreeExchangeEnergy(h, eri, occupations, two_rdm_h, two_rdm_x);
  logTiming(label + " JK-only functional energy evaluated (" + functional_name + ")", t_start,
            t_checkpoint, timing_records);
  const double total_energy = electronic_energy + nuclear_repulsion_energy;

  double occupation_sum = 0.0;
  for (const double n : occupations) occupation_sum += n;

  std::ostringstream out;
  out << "\n"
      << label
      << " fractional-occupation RDMFT functional evaluation (Occ_opt/JK_only.h + "
         "Occ_opt/OccupationInit.h, on the converged HF/DHF orbitals):\n";
  out << "  Functional: " << functional_name << "   Occupation init: " << occupation_init_name;
  if (occupation_init_method == rerdmft::OccupationInitMethod::kFermiDirac) {
    out << "   Temperature: " << temperature_kelvin << " K";
  }
  out << "\n";
  out << "  Sum of fractional occupations (expect " << n_electrons
      << "): " << std::setprecision(10) << occupation_sum << std::setprecision(6) << "\n";
  out << "  Electronic energy: " << std::setprecision(10) << electronic_energy
      << std::setprecision(6) << " Hartree\n";
  out << "  Nuclear repulsion energy: " << std::setprecision(10) << nuclear_repulsion_energy
      << std::setprecision(6) << " Hartree\n";
  out << "  Total " << functional_name << " (fractional-occupation) energy: "
      << std::setprecision(10) << total_energy << std::setprecision(6) << " Hartree\n";

  // Occupation-number OPTIMIZATION (Occ_opt/SQP.h), at FIXED orbitals
  // and one-/two-electron integrals (h/eri never change below) --
  // minimize the SAME functional's energy (Occ_opt/OccupationEnergy.h,
  // an explicit function of occupations alone) subject to sum(n)=
  // n_electrons and the N-representability box bounds, starting from
  // `occupations_active` itself. Restricted to the SAME active/inactive
  // split as the occupation-generation step above -- for C4_DHF,
  // `embed` below keeps the negative-energy branch pinned at EXACTLY
  // zero throughout (it is never an SQP optimization variable at all,
  // not merely initialized to zero), preserving the no-pair
  // approximation through the optimization too.
  //
  // Box bounds are kept slightly INSIDE the true [0,1] (by the same
  // kOccupationEpsilon generateInitialOccupations already redistributed
  // `occupations_active` into above, so it is ALREADY a feasible
  // starting point here, with no further clamping needed): several
  // functionals here (e.g. MBB's sqrt(n_i*n_j)) have a SECOND
  // DERIVATIVE that genuinely diverges as an occupation approaches 0 or
  // 1 (a real mathematical feature of these functionals, not a bug --
  // see Occ_opt/JK_only.h's D11/D12), which would feed an infinite
  // Hessian entry into the active-set QP's linear solve if a variable
  // ever reached the TRUE boundary -- no finite regularization can fix
  // a literal infinity, hence keeping the feasible region an interior
  // box throughout (see Occ_opt/OccupationInit.h).
  const std::size_t n_active = occupations_active.size();
  const rerdmft::Matrix<double> a_eq(1, n_active, 1.0);
  const std::vector<double> b_eq = {n_electrons};
  const std::vector<double> lb(n_active, kOccupationEpsilon);
  const std::vector<double> ub(n_active, 1.0 - kOccupationEpsilon);

  auto embed = [&](const std::vector<double>& active) {
    std::vector<double> full(n_total, 0.0);
    for (std::size_t i = 0; i < n_active; ++i) full[n_inactive_below + i] = active[i];
    return full;
  };
  const rerdmft::SqpValueFn value_fn = [&](const std::vector<double>& x) {
    return rerdmft::jkFunctionalEnergy(h, eri, embed(x), functional, f_l);
  };
  const rerdmft::SqpGradientFn gradient_fn = [&](const std::vector<double>& x) {
    const auto full_grad = rerdmft::jkFunctionalGradient(h, eri, embed(x), functional, f_l);
    return std::vector<double>(
        full_grad.begin() + static_cast<std::ptrdiff_t>(n_inactive_below),
        full_grad.begin() + static_cast<std::ptrdiff_t>(n_inactive_below + n_active));
  };
  const rerdmft::SqpHessianFn hessian_fn = [&](const std::vector<double>& x) {
    const auto full_hess = rerdmft::jkFunctionalHessian(h, eri, embed(x), functional, f_l);
    rerdmft::Matrix<double> active_hess(n_active, n_active);
    for (std::size_t r = 0; r < n_active; ++r) {
      for (std::size_t s = 0; s < n_active; ++s) {
        active_hess(r, s) = full_hess(n_inactive_below + r, n_inactive_below + s);
      }
    }
    return active_hess;
  };

  out << "\n  SQP occupation-number optimization (Occ_opt/SQP.h, FIXED orbitals/integrals,\n"
      << "  sum(n) = " << n_electrons << " constraint, " << kOccupationEpsilon << " <= n_p <= "
      << (1.0 - kOccupationEpsilon) << "):\n";
  try {
    const auto sqp_result =
        rerdmft::solveSqp(value_fn, gradient_fn, hessian_fn, a_eq, b_eq, lb, ub, occupations_active);
    logTiming(label + " SQP occupation-number optimization complete (" + functional_name + ")",
              t_start, t_checkpoint, timing_records);
    double optimized_occupation_sum = 0.0;
    for (const double n : sqp_result.x) optimized_occupation_sum += n;
    const double optimized_total_energy = sqp_result.objective_value + nuclear_repulsion_energy;
    out << "    " << (sqp_result.converged ? "Converged" : "Did NOT converge") << " after "
        << sqp_result.iterations << " iteration(s)\n";
    out << "    Optimized sum of occupations (expect " << n_electrons
        << "): " << std::setprecision(10) << optimized_occupation_sum << std::setprecision(6)
        << "\n";
    out << "    Optimized electronic energy: " << std::setprecision(10)
        << sqp_result.objective_value << std::setprecision(6) << " Hartree\n";
    out << "    Optimized total " << functional_name << " energy: " << std::setprecision(10)
        << optimized_total_energy << std::setprecision(6) << " Hartree ("
        << (optimized_total_energy <= total_energy ? "<=" : ">")
        << " the initial-occupations value above, as expected for a minimization)\n";
    // Rounds to the SAME 5 decimals actually printed below, so the
    // reported sum matches what a reader would get by adding up the
    // displayed digits themselves (rather than the full-precision
    // values, which would make an "expect close to n_electrons" claim
    // confusing next to numbers that look like they should sum
    // exactly).
    auto round5 = [](double v) { return std::round(v * 1e5) / 1e5; };
    out << "    Optimized occupation numbers (index: n_p, global index into the full "
           "orbital/spinor space, fixed 5 decimals):\n";
    out << std::fixed << std::setprecision(5);
    double displayed_occupation_sum = 0.0;
    if (label == "C4_DHF") {
      // Two columns, even/odd side by side -- SAME adjacent-index
      // Kramers-pair convention already used elsewhere in this file
      // (e.g. "Converged one-body (Fock_ortho) state energies"): lets
      // the printed numbers themselves be visually checked to confirm
      // Kramers partners get the SAME occupation (a pure function of
      // orbital energy, and Kramers partners are degenerate in energy
      // -- see [[project-jk-only]]'s own confirmation of this).
      for (std::size_t i = 0; i + 1 < n_active; i += 2) {
        const std::size_t g0 = n_inactive_below + i;
        const std::size_t g1 = n_inactive_below + i + 1;
        out << "      " << std::setw(6) << g0 << std::setw(12) << sqp_result.x[i]
            << std::setw(10) << g1 << std::setw(12) << sqp_result.x[i + 1] << "\n";
        displayed_occupation_sum += round5(sqp_result.x[i]) + round5(sqp_result.x[i + 1]);
      }
      if (n_active % 2 == 1) {
        const std::size_t g = n_inactive_below + n_active - 1;
        out << "      " << std::setw(6) << g << std::setw(12) << sqp_result.x[n_active - 1]
            << "\n";
        displayed_occupation_sum += round5(sqp_result.x[n_active - 1]);
      }
    } else {
      for (std::size_t i = 0; i < n_active; ++i) {
        out << "      " << std::setw(6) << (n_inactive_below + i) << std::setw(12)
            << sqp_result.x[i] << "\n";
        displayed_occupation_sum += round5(sqp_result.x[i]);
      }
    }
    out << std::defaultfloat << std::setprecision(6);
    out << "    Sum of the occupation numbers shown above, at that same 5-decimal precision "
           "(expect close to "
        << n_electrons << "): " << std::setprecision(10) << displayed_occupation_sum
        << std::setprecision(6) << "\n";
  } catch (const std::exception& e) {
    out << "    FAILED: " << e.what() << "\n";
  }

  return out.str();
}

// Builds NON_REL's (Large,Large|Large,Large) two-electron tensor, or --
// when input.cache_integrals() is set -- loads it from (and, on a miss,
// saves it to) a disk cache keyed by the Large basis alone. See
// IntegralCache.h: this tensor does not depend on SPEED_OF_LIGHT, so runs
// that only differ in that setting (e.g. the water-c*.inp series) share
// one cache entry.
rerdmft::PackedTwoElectronTensor buildOrLoadNonRelEri(
    const rerdmft::Input& input, const std::vector<rerdmft::BasisFunction>& large_basis) {
  const std::uint64_t fingerprint = rerdmft::basisFingerprint(large_basis);
  if (input.cache_integrals()) {
    const std::string path =
        input.cache_dir() + "/nonrel_eri_" + rerdmft::fingerprintToHex(fingerprint) + ".bin";
    rerdmft::PackedTwoElectronTensor cached;
    if (rerdmft::loadPackedTwoElectronTensor(path, fingerprint, large_basis.size(), cached)) {
      std::cout << "NON_REL two-electron integrals: loaded from disk cache (" << path << ")\n";
      return cached;
    }
    rerdmft::PackedTwoElectronTensor built = rerdmft::twoElectronIntegralsPacked(large_basis);
    rerdmft::savePackedTwoElectronTensor(path, fingerprint, built);
    std::cout << "NON_REL two-electron integrals: wrote disk cache (" << path << ")\n";
    return built;
  }
  return rerdmft::twoElectronIntegralsPacked(large_basis);
}

// Same idea as buildOrLoadNonRelEri, for C4_DHF's RKB spinor two-electron
// tensor. Its fingerprint combines the Large and Small basis fingerprints
// (rkbCoefficients, and hence this tensor, is a pure function of the two
// bases -- see IntegralCache.h -- so, again, SPEED_OF_LIGHT does not
// enter the cache key).
rerdmft::RkbTwoElectronTensor buildOrLoadC4SpinorEri(
    const rerdmft::Input& input, const std::vector<rerdmft::BasisFunction>& large_basis,
    const std::vector<rerdmft::BasisFunction>& small_basis,
    const rerdmft::Matrix<std::complex<double>>& rkb_coefficients) {
  const std::size_t dim = 4 * large_basis.size();
  const std::uint64_t fingerprint = rerdmft::combineFingerprints(
      rerdmft::basisFingerprint(large_basis), rerdmft::basisFingerprint(small_basis));
  if (input.cache_integrals()) {
    const std::string path =
        input.cache_dir() + "/c4_eri_" + rerdmft::fingerprintToHex(fingerprint) + ".bin";
    rerdmft::RkbTwoElectronTensor cached;
    if (rerdmft::loadRkbTwoElectronTensor(path, fingerprint, dim, cached)) {
      std::cout << "C4_DHF two-electron integrals: loaded from disk cache (" << path << ")\n";
      return cached;
    }
    rerdmft::RkbTwoElectronTensor built =
        rerdmft::rkbTwoElectronIntegrals(large_basis, small_basis, rkb_coefficients);
    rerdmft::saveRkbTwoElectronTensor(path, fingerprint, built);
    std::cout << "C4_DHF two-electron integrals: wrote disk cache (" << path << ")\n";
    return built;
  }
  return rerdmft::rkbTwoElectronIntegrals(large_basis, small_basis, rkb_coefficients);
}

void printAoList(const std::string& label,
                  const std::vector<rerdmft::BasisFunction>& functions,
                  const std::vector<rerdmft::NormalizationCheck>& normalization) {
  std::cout << "\n" << label << " (" << functions.size()
             << " total), normalized via libcint overlap integrals:\n";
  for (std::size_t i = 0; i < functions.size(); ++i) {
    const auto& fn = functions[i];
    const auto& check = normalization[i];
    std::cout << "  " << std::setw(2) << fn.element << "  "
               << rerdmft::angularMomentumLabel(fn.l) << "(" << fn.cartesian.lx
               << fn.cartesian.ly << fn.cartesian.lz << ")  "
               << "center=(" << fn.x << ", " << fn.y << ", " << fn.z << ")  "
               << "nprim=" << fn.exponents.size() << "  "
               << "S_self(before)=" << check.self_overlap_before << "  "
               << (check.was_renormalized ? "renormalized" : "already normalized")
               << "\n";
  }
}

struct BlockNorms {
  double max_hermiticity_error = 0.0;
  double max_large_large = 0.0;
  double max_large_small = 0.0;
  double max_small_small = 0.0;
};

BlockNorms analyzeBlocks(const rerdmft::Matrix<std::complex<double>>& m,
                          std::size_t n_large_total) {
  BlockNorms norms;
  for (std::size_t p = 0; p < m.rows(); ++p) {
    for (std::size_t q = 0; q < m.cols(); ++q) {
      norms.max_hermiticity_error =
          std::max(norms.max_hermiticity_error, std::abs(m(p, q) - std::conj(m(q, p))));
      const bool p_large = p < n_large_total;
      const bool q_large = q < n_large_total;
      const double v = std::abs(m(p, q));
      if (p_large && q_large) {
        norms.max_large_large = std::max(norms.max_large_large, v);
      } else if (!p_large && !q_large) {
        norms.max_small_small = std::max(norms.max_small_small, v);
      } else {
        norms.max_large_small = std::max(norms.max_large_small, v);
      }
    }
  }
  return norms;
}

void printMatrixDiagnostics(const std::string& label,
                             const rerdmft::Matrix<std::complex<double>>& m,
                             std::size_t n_large_total) {
  const BlockNorms norms = analyzeBlocks(m, n_large_total);
  std::cout << "\n" << label << ":\n";
  std::cout << "  Dimensions: " << m.rows() << " x " << m.cols() << "\n";
  std::cout << "  Max |M - M^dagger| (Hermiticity check): " << norms.max_hermiticity_error << "\n";
  std::cout << "  Max |M| within Large-Large block: " << norms.max_large_large << "\n";
  std::cout << "  Max |M| within Large-Small block: " << norms.max_large_small << "\n";
  std::cout << "  Max |M| within Small-Small block: " << norms.max_small_small << "\n";
}

void printWelcomeBanner() {
  constexpr int kWidth = 70;
  auto center = [](const std::string& text) {
    const int pad = kWidth - static_cast<int>(text.size());
    const int left = pad > 0 ? pad / 2 : 0;
    const int right = pad > 0 ? pad - left : 0;
    return std::string(static_cast<std::size_t>(left), ' ') + text +
           std::string(static_cast<std::size_t>(right), ' ');
  };
  const std::string border = "+" + std::string(kWidth, '-') + "+";
  const std::string blank = "|" + std::string(kWidth, ' ') + "|";

  std::cout << border << "\n";
  std::cout << blank << "\n";
  std::cout << "|" << center("R e R D M F T") << "|\n";
  std::cout << blank << "\n";
  std::cout << "|" << center("Relativistic Reduced Density Matrix Functional Theory") << "|\n";
  std::cout << "|" << center("-- developed with Claude --") << "|\n";
  std::cout << blank << "\n";
  std::cout << "|" << center("M. Rodriguez-Mayorga, PhD.") << "|\n";
  std::cout << "|" << center("marm3.14@gmail.com") << "|\n";
  std::cout << blank << "\n";
  std::cout << border << "\n\n";
}

